import json from "./delays.json";
import type { DataSource, RankedData } from "@/lib/types";

// Generated by scripts/extract_delays.py — never edit the JSON by hand. Server-only.
type Mode = { year: string; lastMonth: string; codes: DataSource; minutes: number; delays: number };
export const DELAYS = json as unknown as RankedData & { modes: { subway: Mode; bus: Mode; streetcar: Mode } };
